package com.meshcrossway.android;

import java.net.URI;
import java.util.*;
import java.security.SecureRandom;

/** Official ChannelSet protobuf URL. Never fetches URLs or logs their contents. */
final class MtChannelLink {
    final List<byte[]> channels;final byte[] lora;
    MtChannelLink(List<byte[]> channels,byte[] lora){if(channels.isEmpty()||channels.size()>8)throw Wire.bad("A channel link must contain 1–8 channels");this.channels=new ArrayList<>();for(byte[] ch:channels){validate(ch);this.channels.add(ch.clone());}Set<Integer> tags=new HashSet<>();for(Wire.F f:Wire.fields(lora)){if(!tags.add(f.tag))throw Wire.bad("Duplicate LoRa setting");if(Arrays.asList(1,2,3,4,5,11).contains(f.tag)&&f.wire!=0||Arrays.asList(6,14).contains(f.tag)&&f.wire!=5)throw Wire.bad("Invalid LoRa field type");}this.lora=lora.clone();}
    static void validate(byte[] settings){List<Wire.F> fs=Wire.fields(settings);Set<Integer> seen=new HashSet<>();for(Wire.F f:fs)if(!seen.add(f.tag)||f.tag<1||f.tag>7)throw Wire.bad("Unsupported or duplicate Meshtastic channel setting");String name=Wire.utf8(Wire.bytes(fs,3));Wire.optionalText(name,11);if(name.chars().anyMatch(Character::isISOControl))throw Wire.bad("Use a single-line channel name");byte[] key=Wire.bytes(fs,2);if(key.length!=0&&key.length!=1&&key.length!=16&&key.length!=32)throw Wire.bad("Use a default key, no encryption, AES-128 or AES-256");if(key.length==1&&(key[0]&255)>10)throw Wire.bad("Unknown default channel key");for(int tag:new int[]{2,3,7}){Wire.F f=Wire.field(fs,tag);if(f!=null&&f.wire!=2)throw Wire.bad("Invalid channel field type");}for(int tag:new int[]{1,5,6}){Wire.F f=Wire.field(fs,tag);if(f!=null&&f.wire!=0)throw Wire.bad("Invalid channel field type");}Wire.F id=Wire.field(fs,4);if(id!=null&&id.wire!=5)throw Wire.bad("Invalid channel ID");Wire.fields(Wire.bytes(fs,7));}
    static byte[] key(String hex){if(hex==null||!hex.matches("(?:[0-9a-fA-F]{2})*"))throw Wire.bad("Enter a hexadecimal channel key");byte[] key=Wire.unhex(hex);validate(new Wire.Out().bytes(2,key).array());return key;}
    static byte[] privateSettings(String name){byte[] key=new byte[32];new SecureRandom().nextBytes(key);byte[] s=new Wire.Out().bytes(2,key).bytes(3,Wire.text(name,11)).array();validate(s);return s;}
    String link(){Wire.Out out=new Wire.Out();for(byte[] c:channels)out.bytes(1,c);if(lora.length>0)out.bytes(2,lora);byte[] body=out.array();if(body.length>512)throw Wire.bad("Channel link is too large; share fewer channels");return "https://meshtastic.org/e/#"+Base64.getUrlEncoder().withoutPadding().encodeToString(body);}
    static MtChannelLink parse(String text){try{if(text==null||text.length()>2048)throw Wire.bad("Invalid Meshtastic link");URI u=new URI(text.trim());if(!"https".equalsIgnoreCase(u.getScheme())||!Arrays.asList("meshtastic.org","www.meshtastic.org").contains(u.getHost())||!("/e/".equals(u.getPath())||"/e".equals(u.getPath()))||u.getUserInfo()!=null||u.getPort()!=-1||u.getRawQuery()!=null)throw Wire.bad("Paste an official https://meshtastic.org/e/# channel link");String data=u.getRawFragment();if(data==null||!data.matches("[A-Za-z0-9_+/=-]+"))throw Wire.bad("Invalid channel link data");byte[] bytes;try{bytes=Base64.getUrlDecoder().decode(data);}catch(IllegalArgumentException e){bytes=Base64.getDecoder().decode(data);}List<byte[]> channels=new ArrayList<>();byte[] lora=Wire.EMPTY;boolean hasLora=false;for(Wire.F f:Wire.fields(bytes)){if(f.wire!=2)throw Wire.bad("Invalid channel set");if(f.tag==1)channels.add(f.bytes);else if(f.tag==2&&!hasLora){lora=f.bytes;hasLora=true;}else throw Wire.bad("Unsupported channel set field");}return new MtChannelLink(channels,lora);}catch(java.net.URISyntaxException e){throw Wire.bad("Invalid Meshtastic channel link");}}
    static String name(byte[] settings){String name=Wire.utf8(Wire.bytes(Wire.fields(settings),3));return name.isEmpty()?"Default (preset name)":name;}
    // Keep RF parameters while preserving the local region, TX policy, power and unrelated fields.
    byte[] mergedLora(byte[] current){byte[] result=current;List<Wire.F> fs=Wire.fields(lora);for(int tag:new int[]{1,2,3,4,5,6,11,14}){Wire.F f=Wire.field(fs,tag);result=tag==6||tag==14?Wire.floatField(result,tag,f==null?0:Float.intBitsToFloat((int)f.number)):Wire.replace(result,tag,f==null?0:f.number);}return result;}
    boolean sameLora(byte[] current){return lora.length==0||MtLora.readbackDifference(current,mergedLora(current)).isEmpty();}
}
